import { ClassLevelId, Difficulty } from '../../types';
import { buildSubjectHyper72, HyperBundle, HyperTopicTuple, mergeHyperBundles } from './engine';

type CompactItem = [slug: string, title: string, keyNotion: string, rule: string, trap: string, cls: ClassLevelId, diff?: Difficulty];

function expandTopics(subjectLabel: string, items: CompactItem[]): HyperTopicTuple[] {
  return items.map(([slug, title, keyNotion, rule, trap, cls, diff]) => [
    slug,
    title,
    `Maîtrise complète de « ${title} » en ${subjectLabel} : concepts clés, méthode et application pratique.`,
    keyNotion,
    rule,
    trap,
    `Cas corrigé (${cls.toUpperCase()}) : appliquer « ${rule} » sur un exercice type de ${title}.`,
    diff ?? (cls === '6e' || cls === '5e' || cls === '4e' ? 'facile' : cls === 'l3' || cls === 'master' ? 'difficile' : 'moyen'),
    cls,
  ]);
}

